window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-177204cba772426e"]={"versions": [{"id": "FIG-177204cba772426e", "releases": ["R4.3.1"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Spezifikation aus der AUTOSAR E2E-Bibliothek (Classic Platform). Dargestellt ist die C-Typdefinition <code>E2E_P22ConfigType</code> im Namensraum <code>E2E::E2E_P22Types::</code>, welche die statischen Konfigurationsparameter für das E2E-Profil 22 festlegt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Struktur <code>«structure» E2E::E2E_P22Types::E2E_P22ConfigType</code> mit folgenden öffentlichen Feldern:</p>\n<ul class=\"fig-list\"><li><code>DataIDList :uint8[16]</code>: Array aus 16 8-Bit-Werten zur Konfiguration der Data-IDs im Profil 22.\n</li><li><code>DataLength :uint16</code>: Gesamtlänge der abgesicherten Daten in Bits.\n</li><li><code>MaxDeltaCounter :uint8</code>: Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Zählerwerten.\n</li><li><code>Offset :uint16</code>: Bit-Offset des E2E-Headers innerhalb der übertragenen Dateneinheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenstruktur ohne dynamisches Eigenverhalten. Die Struktur wird initial definiert und an die Zustandstransitionen bzw. Prüf- und Schutzfunktionen des E2E-Profils 22 (<code>E2E_P22Protect</code> / <code>E2E_P22Check</code>) als schreibgeschützte Referenz übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Konfigurations-Typs für E2E Profile 22 gemäß AUTOSAR_SWS_E2ELibrary. Entwickler müssen sicherstellen, dass die Felder byteweise gemäß Plattform-Endianness und Alignment-Vorgaben konfiguriert werden; die Werte für <code>DataIDList</code>, <code>DataLength</code>, <code>MaxDeltaCounter</code> und <code>Offset</code> müssen sender- und empfängerseitig exakt übereinstimmen.</p>"}, {"id": "FIG-0cffb2ac28fd516f", "releases": ["R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm / Datenstruktur-Spezifikation aus der AUTOSAR E2E-Bibliothek. Dargestellt ist die C-Typdefinition <code>E2E_P22ConfigType</code> im Namensraum <code>E2E_P22Types::</code>, welche die statischen Konfigurationsparameter für das E2E-Profil 22 festlegt.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Struktur <code>«structure» E2E_P22Types::E2E_P22ConfigType</code> mit folgenden öffentlichen Feldern:</p>\n<ul class=\"fig-list\"><li><code>DataIDList: uint8[16]</code>: Array aus 16 8-Bit-Werten zur Konfiguration der Data-IDs im Profil 22.\n</li><li><code>DataLength: uint16</code>: Gesamtlänge der abgesicherten Daten in Bits.\n</li><li><code>MaxDeltaCounter: uint8</code>: Maximal zulässige Differenz zwischen zwei aufeinanderfolgenden Zählerwerten.\n</li><li><code>Offset: uint16</code>: Bit-Offset des E2E-Headers innerhalb der übertragenen Dateneinheit.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Datenstruktur ohne dynamisches Eigenverhalten. Die Struktur wird initial definiert und an die Zustandstransitionen bzw. Prüf- und Schutzfunktionen des E2E-Profils 22 (<code>E2E_P22Protect</code> / <code>E2E_P22Check</code>) als schreibgeschützte Referenz übergeben.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Spezifikation des Konfigurations-Typs für E2E Profile 22 gemäß AUTOSAR_SWS_E2ELibrary. Entwickler müssen sicherstellen, dass die Felder byteweise gemäß Plattform-Endianness und Alignment-Vorgaben konfiguriert werden; die Werte für <code>DataIDList</code>, <code>DataLength</code>, <code>MaxDeltaCounter</code> und <code>Offset</code> müssen sender- und empfängerseitig exakt übereinstimmen.</p>"}], "trans": [{"from": "FIG-177204cba772426e", "to": "FIG-0cffb2ac28fd516f", "fr": "R4.3.1", "tr": "R18-10_R4.4.0_R1.5.0", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Namensraum-Präfix der Datenstruktur von <code>E2E::E2E_P22Types::</code> auf <code>E2E_P22Types::</code> verkürzt.\n</li><li>Typannotationen der Strukturfelder formatiert (überflüssige Leerzeichen vor dem Doppelpunkt entfernt: <code>:uint</code> zu <code>: uint</code>).\n</li></ul>"}]};
